#define main gate1_main
#include "../gate.cpp"
#undef main
#include <zstd.h>

using Frame=std::array<RGB,256>;
static Image crop(const Frame&f,int bx,int by){Image o{};for(int y=0;y<8;y++)for(int x=0;x<8;x++)o[y*8+x]=f[(by*8+y)*16+bx*8+x];return o;}
static double frame_mse(const Frame&a,const Frame&b){double e=0;for(int i=0;i<256;i++)for(int c=0;c<3;c++){double d=a[i][c]-b[i][c];e+=d*d;}return e/(256*3);}
static double aligned_mse(const Frame&cur,const Frame&prev,int dir){double e=0;int n=0;for(int y=0;y<16;y++)for(int x=0;x<16;x++){int px=x-dir;if(px<0||px>=16)continue;for(int c=0;c<3;c++){double d=cur[y*16+x][c]-prev[y*16+px][c];e+=d*d;n++;}}return e/n;}
static Frame moving_edge(int ex){Frame f{};for(int y=0;y<16;y++)for(int x=0;x<16;x++){float v=x<ex?0:255;f[y*16+x]={v,v,v};}return f;}
static Frame diag(int phase){Frame f{};for(int y=0;y<16;y++)for(int x=0;x<16;x++){bool a=x>=y+phase;float v=a?255.0f:0.0f;f[y*16+x]={v,v,v};}return f;}
static Frame gradient(int phase){Frame f{};for(int y=0;y<16;y++)for(int x=0;x<16;x++){float v=std::clamp((x+phase)*16.0f,0.0f,255.0f);f[y*16+x]={v,v,v};}return f;}
static void putblock(std::vector<uint8_t>&v,int b,const std::array<uint8_t,16>&p){std::copy(p.begin(),p.end(),v.begin()+16*b);}
static Frame reconstruct(const std::vector<uint8_t>&p,astcenc_context*ctx){Frame f{};int b=0;for(int by=0;by<2;by++)for(int bx=0;bx<2;bx++,b++){std::array<uint8_t,16>block{};std::copy_n(p.begin()+16*b,16,block.begin());Image d=decode(ctx,block);for(int y=0;y<8;y++)for(int x=0;x<8;x++)f[(by*8+y)*16+bx*8+x]=d[y*8+x];}return f;}
static std::array<uint8_t,16> astc_constant(astcenc_context*ctx,RGB c){std::array<uint8_t,8*8*4> rgba{};for(int i=0;i<64;i++){for(int k=0;k<3;k++)rgba[4*i+k]=uint8_t(c[k]);rgba[4*i+3]=255;}void*slices[]={rgba.data()};astcenc_image im{8,8,1,ASTCENC_TYPE_U8,slices};std::array<uint8_t,16>out{};astcenc_swizzle swz{ASTCENC_SWZ_R,ASTCENC_SWZ_G,ASTCENC_SWZ_B,ASTCENC_SWZ_A};auto e=astcenc_compress_image(ctx,&im,&swz,out.data(),out.size(),0);if(e!=ASTCENC_SUCCESS)throw std::runtime_error(astcenc_get_error_string(e));return out;}
int main(){astcenc_config cfg{};assert(astcenc_config_init(ASTCENC_PRF_LDR,8,8,1,ASTCENC_PRE_MEDIUM,0,&cfg)==ASTCENC_SUCCESS);astcenc_context*ctx=nullptr;assert(astcenc_context_alloc(&cfg,1,&ctx)==ASTCENC_SUCCESS);auto*bsd=new block_size_descriptor{};init_block_size_descriptor(8,8,1,false,4,1.0f,*bsd);
 std::cout<<"kind,case,mode,frame,metric,value,bytes\n";
 for(RGB c: {RGB{0,0,0},RGB{128,64,200},RGB{255,255,255}}){auto p=astc_constant(ctx,c);auto d=decode(ctx,p);Image src;src.fill(c);symbolic_compressed_block parsed{};physical_to_symbolic(*bsd,p.data(),parsed);std::cout<<"constant,"<<int(c[0])<<"-"<<int(c[1])<<"-"<<int(c[2])<<",astcenc,0,mse,"<<mse(src,d)<<",16\n";}
 std::vector<std::pair<std::string,std::vector<Frame>>> seqs;
 std::vector<Frame> edges,diags,grads;for(int i=3;i<=8;i++)edges.push_back(moving_edge(i));for(int i=0;i<6;i++){diags.push_back(diag(i-2));grads.push_back(gradient(i-2));}seqs.push_back({"edge",edges});seqs.push_back({"diagonal",diags});seqs.push_back({"gradient",grads});
 std::vector<std::array<Frame,4>> sheets;for(auto&[name,frames]:seqs){std::vector<Frame> last[3];for(int m=0;m<3;m++)last[m].resize(frames.size());std::vector<uint8_t> base_raw[2],sel_raw;std::vector<Frame> base_dec[2],sel_dec;int total=0,selected=0,fallback=0;std::vector<uint8_t> zbuf(1024);ZSTD_CCtx*zc=ZSTD_createCCtx();assert(zc);assert(!ZSTD_isError(ZSTD_CCtx_setParameter(zc,ZSTD_c_compressionLevel,3)));
  for(size_t fi=0;fi<frames.size();fi++){std::vector<uint8_t> pbase(64),p6(64),p2(64),psel(64);for(int by=0;by<2;by++)for(int bx=0;bx<2;bx++){int b=by*2+bx;Image src=crop(frames[fi],bx,by);bool flat=true;for(int i=1;i<64;i++)if(src[i]!=src[0])flat=false;auto a=flat?astc_constant(ctx,src[0]):encode(src,trials[0],*bsd);auto q=flat?a:encode(src,trials[2],*bsd);if(flat)fallback++;auto da=decode(ctx,a),dq=decode(ctx,q);putblock(pbase,b,a);putblock(p2,b,q);double ea=mse(src,da),eq=mse(src,dq);bool use=eq<ea;putblock(psel,b,use?q:a);selected+=use;total++;}base_raw[0].insert(base_raw[0].end(),pbase.begin(),pbase.end());base_raw[1].insert(base_raw[1].end(),p2.begin(),p2.end());sel_raw.insert(sel_raw.end(),psel.begin(),psel.end());base_dec[0].push_back(reconstruct(pbase,ctx));base_dec[1].push_back(reconstruct(p2,ctx));sel_dec.push_back(reconstruct(psel,ctx));}
  auto compressed=[&](const std::vector<uint8_t>&in){size_t n=ZSTD_compress2(zc,zbuf.data(),zbuf.size(),in.data(),in.size());assert(!ZSTD_isError(n));return n;};auto framesize=64u;auto sumframes=[&](const std::vector<uint8_t>&v){size_t n=0;for(size_t off=0;off<v.size();off+=framesize)n+=compressed(std::vector<uint8_t>(v.begin()+off,v.begin()+off+framesize));return n;};auto nb=sumframes(base_raw[0]),n2=sumframes(base_raw[1]),ns=sumframes(sel_raw);double avgerr[3]{};for(size_t fi=0;fi<frames.size();fi++){avgerr[0]+=frame_mse(frames[fi],base_dec[0][fi]);avgerr[1]+=frame_mse(frames[fi],base_dec[1][fi]);avgerr[2]+=frame_mse(frames[fi],sel_dec[fi]);}for(auto&v:avgerr)v/=frames.size();sheets.push_back({frames.back(),base_dec[0].back(),base_dec[1].back(),sel_dec.back()});std::cout<<"sequence,"<<name<<",baseline,all,selected_blocks,"<<selected<<"/"<<total<<";flatFallback="<<fallback<<",rawbytes="<<base_raw[0].size()<<";zstd="<<nb<<"\n";std::cout<<"sequence,"<<name<<",baseline,all,mean_mse,"<<avgerr[0]<<",zstd="<<nb<<"\n";std::cout<<"sequence,"<<name<<",q2,all,mean_mse,"<<avgerr[1]<<",zstd="<<n2<<"\n";std::cout<<"sequence,"<<name<<",selector,all,mean_mse,"<<avgerr[2]<<",zstd="<<ns<<"\n";std::cout<<"sequence,"<<name<<",selector,all,selected_share,"<<double(selected)/total<<",zstd="<<ns<<"\n";
  for(int m=0;m<3;m++){auto&d=m==0?base_dec[0]:m==1?base_dec[1]:sel_dec;double errs=0,srcerrs=0;int count=0;int dir=name=="gradient"?-1:1;for(size_t fi=1;fi<frames.size();fi++){errs+=aligned_mse(d[fi],d[fi-1],dir);srcerrs+=aligned_mse(frames[fi],frames[fi-1],dir);count++;}const char*label=m==0?"baseline":m==1?"q2":"selector";std::cout<<"temporal,"<<name<<","<<label<<",adjacent_mean,decoded_motion_aligned_mse,"<<errs/count<<",source_motion_aligned_mse="<<srcerrs/count<<"\n";}
  ZSTD_freeCCtx(zc);
 }
 {int s=16,scale=8,w=4*s*scale,h=3*s*scale;std::ofstream f("contact.ppm",std::ios::binary);f<<"P6\n"<<w<<" "<<h<<"\n255\n";for(auto&r:sheets)for(int y=0;y<s;y++)for(int sy=0;sy<scale;sy++)for(int m=0;m<4;m++)for(int x=0;x<s;x++)for(int sx=0;sx<scale;sx++){const auto&c=r[m][y*16+x];for(float v:c)f.put(char(std::clamp(int(std::lround(v)),0,255)));}}
 astcenc_context_free(ctx);delete bsd;}
